  'consent.body':
    'Единственные куки, которые мы советуем, — не для еды: они помогают нам улучшать сайт. Спасибо.',
  'consent.acceptAll': 'Разрешить всё',
  'consent.necessary': 'Только необходимое',
  'consent.settings': 'Выбрать',
  'consent.save': 'Сохранить',
  'consent.analytics.label': 'Аналитика и записи',
  'consent.analytics.desc':
    'Полная аналитика и записи сессий — чтобы мы видели, где друзья собак застревают.',
  'consent.marketing.label': 'Маркетинг',
  "consent.marketing.desc": "Рекламные cookies (например, Meta Pixel), чтобы находить новых друзей собак. Пока мы их не используем; твой выбор вступит в силу, когда начнём.",
