  "heroglyph.flow.dogCharacter.slideLabel": "СЛАЙД",
  "heroglyph.flow.dogCharacter.slideAriaLabel": "Следующий слайд с характером",
  "heroglyph.flow.dogCharacter.slide.guardian.title": "Страж (Око Дого)",
  "heroglyph.flow.dogCharacter.slide.player.title": "Игрок (Крылатый мяч)",
  "heroglyph.flow.dogCharacter.slide.energizer.title": "Энерджайзер (Полный заряд)",
  "heroglyph.flow.dogCharacter.slide.maverick.title": "Бунтарь (Пиратский знак)",
  "heroglyph.flow.dogCharacter.slide.waterlover.title": "Водолюб (Волны)",
  "heroglyph.flow.dogCharacter.slide.gourmet.title": "Гурман (Бесконечная миска)",
  "heroglyph.flow.dogCharacter.slide.lover.title": "Обнимашка (Амур)",
  "heroglyph.flow.dogCharacter.slide.chiller.title": "Лежебока (Диван)",
  "heroglyph.flow.dogCharacter.slide.guardian.desc": "Стережёт дверь, будто это врата в загробный мир. Сначала лает, а вопросы — никогда.",
  "heroglyph.flow.dogCharacter.slide.player.desc": "Продаст душу за ещё один бросок мяча. Высшая радость — любимая игрушка.",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "Выключателя нет. Батареек не нужно. Самый частый вопрос: на чём сидит этот пёс?",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "Современный пират со своим миром и своими правилами. Избирательный слух — его первый закон.",
  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "Собаки бывают двух видов — и один из них легко спутать с рыбой. Мокрая шерсть: 100 % счастья.",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "Еда — это миссия. Полная отдача, ноль сомнений — и доест всё, что осталось у тебя в тарелке.",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "Чужих для него не существует. Почтальона встречает как давно потерянную родственную душу. Каждый раз.",
  "heroglyph.flow.dogCharacter.slide.chiller.desc": "Освоил древнее искусство не делать абсолютно ничего — и делает это красиво.",
  "heroglyph.flow.message.done": "Готово",
