  "pack.nature.intro.title": "Кто твоя собака?",
  "pack.nature.intro.body": "Двадцать два вопроса и один чек-лист. Ты узнаешь, из чего сделана твоя собака, какую работу она выполняет для семьи и куда сейчас склоняется её баланс.",
