  "pack.wizard.welcome.title": "Привет, человек!",
  "pack.wizard.k0.title": "Добро пожаловать в DOGYPT!",
  "pack.wizard.k0.vitaj": "Я проведу тебе быструю экскурсию по нашему храму, чтобы ты не бродил тут растерянный. Согласен?",
  "pack.wizard.k0.dar": "Получишь значок!",
  "pack.wizard.k0.ano": "Да",
  "pack.wizard.k0.neskor": "Позже",
  "pack.wizard.k0.feed": "<b>FEED.</b> Главный экран и классическая лента постов, как в Instagram (конечно, с контентом получше!) Можешь следить за новостями, добавлять фото, реагировать, вдохновляться…",
  "pack.wizard.k0.mapa": "<b>КАРТА.</b> Вместе мы создаём собачий мир, где найдётся всё важное. Мы постоянно над ней работаем, улучшаем её и добавляем новое. Спасибо за помощь и терпение!",
  "pack.wizard.k0.labka": "<b>ЛАПКА.</b> Кнопка действия, которой ты добавляешь вещи в зависимости от экрана, на котором находишься!",
  "pack.wizard.k0.ainubis": "<b>МОЗГ AINUBIS.</b> Обучающая часть с собачьими знаниями, полезным скроллингом и подкастами. Контента становится всё больше, в том числе благодаря вам.",
  "pack.wizard.k0.menu": "Наверху <b>ТВОЙ ПРОФИЛЬ</b>, внизу <b>ТВОЯ СТАЯ</b>. Двойное нажатие на фото открывает второй вариант, как в Instagram.",
  "pack.wizard.k1.fotka": "<b>МОЯ СТАЯ.</b> Здесь все документы твоих собак. Держать всю информацию о собаке в одном месте это ответственный и полезный поступок. Нажми сюда и выбери её лучшее фото.",
  "pack.wizard.k1.zivot": "<b>ЖИЗНЬ.</b> Голая реальность в месяцах: сколько обычно живёт эта порода и сколько при лучшем уходе. Чтобы ты не откладывал приключения «на потом».",
  "pack.wizard.k1.dennik": "<b>ДНЕВНИК.</b> Здесь хранятся все ваши ежедневные записи. Ты добавляешь их через регулярную запись дня.",
  "pack.wizard.k1.vyplnit": "<b>DOG ID</b> это подробный квиз о твоей собаке. Всю информацию о ней оценит, например, ветеринар, а также я, когда тебе понадобится совет именно для вас. Нажми Заполнить, и начнём.",
  "pack.wizard.k2.levely": "Твои уровни в DOGYPT: <b>Слуга</b> = годы с собакой, <b>Паломник</b> = походы/километры, <b>Ученик</b> = знания/свитки.",
  "pack.wizard.k2.zapis": "<b>Запись дня</b> это быстрая сводка того, что вы вместе пережили. Можно задним числом записать и прошлые дни, и спланировать наперёд.",
  "pack.wizard.k3.pas": "Здесь самые свежие <b>уведомления</b>, <b>сообщения</b> и меню <b>SOS</b>.",
  "pack.wizard.k4.vrstvy": "<b>Слои:</b> фильтр, которым ты настроишь, что видишь на карте: гадюки, места для ночёвки, ветеринары, TRIPWISH…",
  "pack.wizard.k4.vylety": "Походы и события. Пройдёшь маршрут, отметишь его, и километры добавятся.",
  "pack.wizard.k4.labka": "Свой поход создашь через лапку. Это правда easy, накликаешь его за 3 минутки.",
  "pack.wizard.k5.cta": "<b>SNIFFER</b> ищет друзей для походов. Когда вы оба дадите друг другу SNIFF, сможете переписываться и договориться о прогулке.",
  "pack.wizard.k6.planes": "<b>Свитки</b> это короткое чтение на разные темы. <b>Чат</b> знает весь этот мозг. <b>Источники</b> это библиотека, которую можешь пополнить и ты, например книгой или статьёй.",
  "pack.wizard.k6.zvitky": "Каждый прочитанный свиток засчитывается в твой прогресс. Сколько ты изучаешь собаку, столько ты её по-настоящему любишь.",
  "pack.wizard.k.odz.uvod": "Первый день в храме",
