  "pack.wizard.k.novinky.title": "Что нового",
  "pack.wizard.k.novinky.body": "В храме появились комнаты. Когда рядом со мной загорится ключик, у меня есть для тебя новая. За каждую комнату ты откроешь дверь и получишь значок. Первый твой за эту новость.",
  "pack.wizard.k.novinky.ok": "Понятно",
