  "pack.wizard.k0.fotkaTuk": "Нажми на своё фото.",
  "pack.wizard.k0.aiTuk": "И напоследок я. Нажми на мою иконку.",
  "pack.wizard.k0.preslov": "Мою иконку ты найдёшь почти на каждом экране, я всегда здесь для тебя. Когда что-то не работает, нажми на <b>мишень</b>: я сделаю скриншот, а ты просто отметишь место, без фото в телефоне. А когда рядом со мной загорится <b>ключик</b>, у меня для тебя новинка, которую я объясню.",
  "pack.wizard.k1.navFotka": "Нажми на своё фото.",
  "pack.wizard.k1.navSvorka": "Нажми на <b>СТАЮ</b>.",
  "pack.wizard.k1.zivotTuk": "Нажми на <b>Жизнь</b>.",
