  "pack.wizard.k2.navFotka": "Нажми на своё фото.",
  "pack.wizard.k2.navProfil": "Нажми на <b>ПРОФИЛЬ</b>.",
  "pack.wizard.k2.bones": "<b>BONES</b> — внутренняя валюта DOGYPT. Ты получаешь их за каждого друга, которого приводишь. Позже их можно будет обменять, например, на мерч.",
  "pack.wizard.k2.pozvi": "<b>Пригласить</b> отправляет твою ссылку друзьям. DOGYPT растёт именно так, стань частью нашего роста.",
  "pack.wizard.k2.upravit": "<b>Редактировать профиль:</b> здесь ты настроишь свои данные, то, как тебя видят другие, и настройки приложения.",
  "pack.wizard.k2.labkaTuk": "Нажми на <b>лапку</b>.",
  "pack.wizard.k3.kolesoTuk": "Нажми на <b>спасательный круг</b>.",
  "pack.wizard.k3.koleso": "<b>SOS.</b> Полезные функции, которые могут спасти жизнь, если твоя собака в опасности. Верим, что тебе никогда не придётся ими пользоваться, но лучше быть готовым!",
  "pack.wizard.k4.navTuk": "Нажми на <b>КАРТУ</b>.",
