  "pack.wizard.toDogs.body": "Здесь живёт твоя стая. Нажми на {dog}, чтобы открыть его DOG ID — чем больше ты мне о нём расскажешь, тем лучше я смогу тебе советовать.",
  "pack.wizard.toDogs.bodyNoDog": "Здесь будет жить твоя стая. Пока она пуста — нажми на «+» и добавь первую собаку.",
  "pack.wizard.toDogs.cta": "Понятно",
