  "onepage.need.misGoal": "сила, способная сделать столько добра.",
  "onepage.need.goal": "Наша цель",
  "onepage.need.step": "Следующий шаг",
  "onepage.need.want": "Присоединяйся к миссии",
  "onepage.need.cta": "Присоединяйся к миссии",
  "onepage.need.createGlyph": "Создай heroglyph для своей собаки",
  "onepage.need.ctasub": "Забирай свой номер —",
  "onepage.need.tailLead": "Единственное, что можно сделать —",
  "onepage.need.tailFree": "это бесплатно",
  "film.keepScrolling": "Листай дальше",
  "onepage.hbook.0.title": "Давным-давно…",
  "onepage.hbook.0.glyph": "Heroglyph Hekthor",
  "onepage.hbook.0.sub": "Hekthor · пёс #1",
  "onepage.hbook.0.cap": "Зеркало",
  "onepage.hbook.1.ini": "Р",
  "onepage.hbook.1.lead": "одился нежеланным. Выброшенный в коробке, где с братьями ждал смерти.",
  "onepage.hbook.1.txt": "Восемь крошечных душ оказались в приюте. Семеро из них нашли дом. Остался лишь один — самый большой, с самым большим темпераментом. Через год, по чистой случайности, он встретил Матея, который собаку не планировал. Проскочила искра, и с июня 2017 они вместе идут по жизни.",
  "onepage.hbook.1.cap": "Восемь в коробке",
  "onepage.hbook.2.ini": "О",
  "onepage.hbook.2.lead": "н спас человеческую жизнь. Он пришёл в самый трудный её период.",
  "onepage.hbook.2.txt": "В самые тёмные времена он был для Матея опорой — вытащил его из дурных мыслей, из квартиры на природу. Сначала они открывали ближайшие улочки, потом рощи и горы. Прошли всю Словакию (820 км) и совершили road trip-ы по Европе. Их объединили приключения и свободная жизнь в пути.",
  "onepage.hbook.2.cap": "Из офиса в мир",
  "onepage.hbook.3.ini": "Е",
  "onepage.hbook.3.lead": "го чистая душа принесла видение глобального движения для любителей собак.",
  "onepage.hbook.3.txt": "Жизнь с собакой — самая прекрасная глава в жизни каждого человека. Собачники — совсем другой вид людей: они снова и снова решают одни и те же специфические проблемы, и их объединяет любовь к собакам. А что, если превратить эту историю во что-то полезное?",
  "onepage.hbook.3.cap": "Рождается видение",
  "onepage.hbook.4.ini": "Д",
  "onepage.hbook.4.lead": "есять прекраснейших лет позади, и минимум десять ещё впереди!",
  "onepage.hbook.4.txt": "Hekthor вдохновил Матея узнавать о собаках всё — психологию, дрессировку, спорт, а больше всего — долголетие. Все эти знания будут служить всем в DOGYPT: не очередная модная соцсеть, а сеть со смыслом и содержательным контентом. И всё это благодаря «обычной» собаке из приюта.",
  "onepage.hbook.4.cap": "Основатель #1",
  "onepage.hbook.5.ini": "С",
  "onepage.hbook.5.lead": "егодня он живёт в Словакии — в лесах, горах и у озёр.",
  "onepage.hbook.5.txt": "Больше всего он любит апортировать из воды. Он в отличной форме, очень разумный, скромный и лучший компаньон, о каком можно мечтать. Когда нас нет на улице, дома он сторожит двух котов, Гэри и Ибу, которых спас с улицы.",
  "onepage.hbook.5.cap": "Страж дома",
