  "magnet.lock.save.h": "Сохрани её как догиптянин",
  "magnet.lock.save.p": "Это была пробная запись — поездка не сохранилась. Догиптяне хранят поездки в триплисте, собирают километры и баллы, а стая видит, где они побывали.",
  "magnet.lock.login": "Я догиптянин — войти",
