  "magnet.lock.ai.eye": "Эксклюзивный контент",
  "magnet.lock.ai.h": "Only Paws",
  "magnet.lock.ai.p": "Да, у нас тоже есть эксклюзивный контент. Наш про собак, так что его не нужно ни от кого прятать. Он в приложении, а приложение бесплатное.",
  "magnet.lock.ai.stay": "Ещё понюхаю бесплатно",
  "magnet.info.eye": "Что здесь есть",
  "magnet.info.ok": "Понятно",
  "magnet.info.ask": "Что это?",
  "magnet.info.events.h": "События",
  "magnet.info.events.p": "Собачьи события в одном месте — выставки, забеги, встречи, совместные поездки. Добавить событие может любой из стаи. Отметь, идёшь ли ты или тебе интересно, и смотри, кто ещё придёт.",
  "magnet.info.sniffer.h": "SNIFFER",
  "magnet.info.sniffer.p": "Находит тебе компанию для поездок. Показывает любителей собак, которые тебе подходят, — нажми SNIFF, Нет или сразу напиши им. Чтобы не ходить по горам наедине с собственными мыслями.",
  "magnet.info.notif.h": "Уведомления",
  "magnet.info.notif.p": "Здесь приложение рассказывает, что происходит в стае: кто только что присоединился, кто хочет в твою поездку, кто прошёл твой маршрут и кто хочет туда же, куда и ты.",
  "magnet.info.msgs.h": "Сообщения",
  "magnet.info.msgs.p": "Личные сообщения между догиптянами. Договоритесь о совместной поездке, отправь совет по маршруту или наконец спроси, как зовут ту собаку с фото.",
  "magnet.info.wish.h": "TRIPWISH",
  "magnet.info.wish.p": "Мечта, а не план. Отметь место, которое не отпускает, — вершину, город или целую страну — и примерно когда. Стая это видит, и кто тоже хочет, отзовётся.",
  "magnet.info.want.h": "Хочу пойти",
  "magnet.info.want.p": "Поездки, которые ты сохранил с карты. Когда пройдёшь их, они перейдут в пройденные, а тебе начислятся километры и баллы.",
  "magnet.info.chat.h": "Чат с AINUBIS",
  "magnet.info.chat.p": "Ты спрашиваешь, AINUBIS отвечает — о здоровье, питании, воспитании, поездках и о том, почему собака ест траву. У догиптян он под рукой днём и ночью.",
  "magnet.info.forum.h": "Форум",
  "magnet.info.forum.p": "Доска стаи — вопросы, опыт и советы от любителей собак для любителей собак. Мы как раз его доделываем, и догиптяне будут там первыми.",
  "magnet.info.sources.h": "Источники",
  "magnet.info.sources.p": "На чём стоит мозг AINUBIS: более 12 000 страниц A4 — 5,5 миллиона слов из 332 интервью, книг, 151 научного исследования, 894 видео и 264 статей. Никаких «мне сосед сказал» — у каждого свитка видно, откуда это. А свой источник может добавить любой догиптянин.",
  "magnet.ai.trips.h": "10 поездок на пробу",
  "magnet.ai.trips.p": "Остальные {n} ты видишь, но войти не можешь — как пёс у дверей мясной лавки. Догиптяне записывают свои поездки, собирают километры и баллы. Я веду счёт и никогда не ошибаюсь. Почти.",
  "magnet.ai.trips.bar": "Остальные поездки ты видишь, но войти не можешь — как пёс у дверей мясной лавки.",
  "magnet.ai.vault.h": "Первый круг — целиком твой",
  "magnet.ai.vault.p": "10 свитков с подкастом о том, откуда взялась собака. Остальные {n} охраняет пёс. Этот пёс это я, и взятку я беру только одну: heroglyph твоей собаки. Он бесплатный.",
  "magnet.ai.vault.bar": "Остальные свитки охраняет пёс. Этот пёс — я.",
  "magnet.ai.stats.h": "Чужие цифры, своя зависть",
  "magnet.ai.stats.bar": "Это километры Matej. Твоих здесь пока нет — Hekthor прокомментировал это одним взглядом.",
  "magnet.ai.article.h": "Эта поездка — за счёт заведения",
  "magnet.ai.article.bar": "Маршрут, парковка и навигация — твои. Комментировать могут только догиптяне — чтобы здесь не лаяли на чужих.",
  "magnet.ai.quiz.h": "Тест — за наш счёт",
