  "login.deleted": "Твой аккаунт будет удалён {date}. Передумал? Войди и отмени удаление.",
  "pack.wizard.ainubis.intro": "Я AINUBIS — главный автономный ИИ-агент DOGYPT. Я слежу за безопасностью и за тем, чтобы всё работало, и я — источник всей информации.",
  "pack.wizard.profile.bones": "Твои BONES и ссылка, чтобы пригласить друзей. Именно так растёт DOGYPT — пожалуйста, будь частью этого.",
  "pack.wizard.profile.pilgrim": "Твой ПИЛИГРИМ: уровень, километры и поездки.",
  "pack.wizard.profile.head": "Имя, прозвище и название стаи. Выбери, как тебя видит стая.",
  "pack.wizard.sniffer.card": "SNIFFER находит компанию для поездок. Сначала заполни профиль на 100 %, потом SNIFF или Нет. Когда вы оба поставите SNIFF, сможете переписываться.",
  "pack.wizard.ainubis.scroll": "DOGSCROLL: свитки один за другим. Прочитай один, «запиши его в мозг» — и загорится зерно.",
  "pack.wizard.ainubis.planes": "Dog Sense — это знания о собаках, ЧАТ — разговор со мной, ФОРУМ — доска объявлений стаи.",
  "pack.wizard.ainubis.me": "МОИ ЗНАНИЯ: я предлагаю интересные, полезные и проверенные знания из мира собак. Сколько ты изучаешь свою собаку, столько ты её и любишь. Каждый прочитанный свиток записывается в твой прогресс и статистику.",
  "pack.wizard.dogs.calendar": "Календарь и вся жизнь твоей собаки в блоках. Записи из дневника попадают сюда сами.",
  "pack.wizard.dogs.quiz": "Тест на характер (3 минуты) покажет стихию твоей собаки и её роль в стае.",
  "pack.wizard.dogs.tiles": "Каждая плитка — часть DOG ID. Чем больше заполнишь, тем лучше я смогу тебе советовать.",
  "pack.wizard.dogs.block": "Твоя собака с первого взгляда: номер, имя и Heroglyph. Процент справа показывает, насколько заполнен DOG ID.",
  "pack.wizard.tripArticle.problem": "Что-то не так? Сообщи — мы разберёмся!",
  "pack.wizard.tripArticle.review": "Оценки лапками и советы от стаи. Оценить можно, когда отметишь поездку как пройденную.",
  "pack.wizard.tripArticle.go": "Навигация до старта и маршрут в телефон в Mapy.com.",
  "pack.wizard.tripArticle.walked": "Прошёл — отметь. Начислятся километры и баллы — сколько, видно на плашке.",
  "pack.wizard.triplist.wish": "TRIPWISH — это место, куда ты когда-нибудь хочешь попасть. Отметь его прямо на карте, чтобы не забыть! «Ищу компанию» видит вся стая, «Только для меня» — только ты. Добавить можно через + ДОБАВИТЬ.",
  "pack.wizard.triplist.want": "Хочу пойти: поездки, которые ты сохранил. Здесь к ним можно вернуться.",
  "pack.wizard.triplist.tabs": "Две вкладки: в TRIPLIST твои поездки, в TRIPSTATS твоя статистика: километры, поездки и горные хребты…",
  "pack.wizard.map.plus": "На карте «+» предлагает, что здесь можно сделать: поездку, TRIPWISH, быструю заметку или событие.",
  "pack.wizard.map.list": "Карта или список поездок — переключай здесь.",
  "pack.wizard.map.note": "Числа в кружках — поездки поблизости: приблизь, и они распадутся на метки. Оставить заметку для стаи (предупреждение, парковка, совет) можно через «+» в центре панели.",
  "pack.wizard.map.layers": "Слои карты: подложка и то, что поверх, — предупреждения стаи, гадюки, места для ночёвки, TRIPWISH…",
  "pack.wizard.map.cats": "Переключайся между тем, что предлагает карта. SNIFFER — это «собачий Tinder», он поможет найти компанию для поездок.",
  "pack.wizard.map.search": "Ищи место прямо на карте или сузь выбор фильтрами: регион, активности, теги.",
  "pack.wizard.map.pilgrim": "Привет, ПИЛИГРИМ! Здесь твой уровень, километры и пройденные поездки. Каждый пройденный км — это балл, и за добавление поездки тоже дают баллы. Нажми сюда, чтобы увидеть свои поездки и статистику.",
  "pack.wizard.navAinubis.body": "А это я. Здесь живёт Dog Sense — знания о собаках, свиток за свитком — и наш чат. Понадобится совет — нажми на меня. Я никуда не ухожу.",
