  'pack.vizia.intro':"Планы, о которых мы мечтаем. Нажми на лапку у тех, что тебе нужны, и оставь комментарий.",
  'pack.vizia.kind.done': "Готово",
  'pack.vizia.kind.wip': "Сейчас работаем",
  'pack.vizia.kruhy.dogma':"6.4: где бы ни встретились двое догиптян с собаками, там есть DOGYPT.",
  'pack.vizia.kruhy.name': "Местные круги",
