  'pack.vizia.land.dogma': "6.3: цель для поколений, не срочная.",
  'pack.vizia.land.name': "DOGYPTLAND",
  'pack.vizia.land.text': "Диснейленд для собак: прекрасный парк, площадки для бега, дрессировочные поля, бассейн, озеро и поросшая травой пирамида с кафе, а ещё ветеринар и другие магазины. Просто рай для собачников.",
  'pack.vizia.liecitelia.name': "Платформа для целителей животных",
  'pack.vizia.liecitelia.text': "Физиотерапевты, зоопсихологи, консультанты по питанию... Специалисты, которые решают проблемы альтернативным путём.",
  'pack.vizia.mapa.name': "Карта прогулок с собакой",
  'pack.vizia.mapa.text': "Прогулки, парковки и места на природе. Запиши прогулку, и она останется в твоём дневнике.",
  'pack.vizia.pomoc.dogma': "1 000 000 собак: вторая династия.",
  'pack.vizia.pomoc.name': "Первая помощь в большом масштабе",
  'pack.vizia.pomoc.text': "Наша главная цель, чтобы у каждой собаки была своя семья. Мы знаем, что это звучит невообразимо, НО если постараться, мы сможем хотя бы приблизиться к этому и спасти миллионы жизней! Собака всегда выполнит свою роль идеального друга, остальное зависит от нас.",
  'pack.vizia.stage.1': "Мечтаем",
  'pack.vizia.stage.2': "Готовим",
  'pack.vizia.stage.3': "Строим",
  'pack.vizia.stena.name': "Стена собак",
  'pack.vizia.stena.text': "Каждая собака со своим героглифом на главной странице.",
  'pack.vizia.title':"Что мы строим",
  'pack.vizia.utulky.dogma': "1 000 собак: первое партнёрство с приютом.",
  'pack.vizia.utulky.name': "Приюты",
  'pack.vizia.utulky.text': "Представь приют, в котором тебе хотелось бы работать! Красивое, современное, чистое место и только очень добрые люди, которые работают с любовью и получают зарплату от нас, от DOGYPT. Приюты перестали бы быть грустными местами и стали бы тренировочными центрами, где у каждой собаки есть своя работа, а при необходимости собаки могли бы помогать, например, в поисках, в больницах или при других катастрофах...",
  'pack.vizia.zbierky.dogma': "Помощь собакам в беде это видение с условием.",
  'pack.vizia.zbierky.name': "Сборы для собак",
  'pack.vizia.zbierky.text': "Дорогая операция? Отправь историю тысячам людей в DOGYPT. Если каждый даст всего 1 евро, лечение вдруг станет доступным, а кошмар превратится в красивую историю нашего единства с собакой, которая будет жить благодаря нам.",
  'ainubis.chat.v2.disclaimer': "AINUBIS в бета-версии. Он отвечает только по нашим свиткам (собачий разум) и может ошибаться. При угрозе здоровью позвони ветеринару.",
