  "pack.misia.member.price": "{p} в месяц",
  "pack.misia.member.once": "разово",
  "pack.misia.member.p": "Ты помогаешь DOGYPT работать! На твои членские взносы работают серверы, AINUBIS и приложение, которое ты держишь в руке. Спасибо.",
  "pack.misia.founder.lead": "Ты Основатель.",
  "pack.misia.founder.p": "Ты среди первых, кто пришёл, когда DOGYPT ещё никто не знал. Этот значок навсегда остаётся с тобой и твоей собакой, и к нему будут прилагаться преимущества.",
  "pack.misia.founder.app": "Если хочешь и дальше поддерживать DOGYPT, мы напишем тебе на e-mail.",
  "pack.misia.founder.web": "Стаю можно поддерживать и регулярно.",
