  "pack.misia.paw.fail": "Не получилось. Попробуй чуть позже.",
  "pack.misia.mine.app": "Пожертвования принимаются на dogypt.com",
  "pack.misia.give": "Пожертвовать",
  "pack.misia.vision": "Наша идея",
  "pack.misia.giftTitle": "Пожертвование",
  "pack.misia.sofar": "До сих пор",
  "pack.misia.perMonth": "В месяц",
  "pack.misia.live": "Цифры берутся из казны в реальном времени, вручную ничего не вписывается.",
  "pack.misia.gift.p": "Добровольное пожертвование, ежемесячно или разово. Оно ничего не открывает — поэтому это пожертвование, а не членство. После комиссии Stripe всё идёт на развитие DOGYPT.",
  "pack.misia.merch.p": "Футболки, нашивки и вещи для собак. Заработанное идёт в казну.",
  "pack.misia.more.p": "Мы добавим только такие источники, которым не нужны ни реклама, ни инвесторы.",
  "pack.misia.run.p": "Чтобы DOGYPT вообще работал: серверы, ИИ, почта, лицензии приложения. Это мы оплачиваем в первую очередь.",
  "pack.misia.app.p": "Разработка приложения: софт, железо, люди и сервисы. Сейчас его строит Матей один и без зарплаты.",
  "pack.misia.res.p": "Как жить с собакой дольше и здоровее: протокол долголетия, ИИ-ветеринар, добавки, которые имеют смысл.",
  "pack.misia.gear.p": "Собственное снаряжение для собак и их людей, например GPS-ошейник.",
  "pack.misia.help.p": "Что DOGYPT даёт собакам в беде. Каждые {n} уходят следующему приюту, сейчас это {shelter}.",
  "pack.misia.v1": "*Наша мечта: DOGYPT, которым может пользоваться каждый собачник.* Всё о собаках и вся жизнь твоей собаки в одном месте.",
  "pack.misia.v2": "Мы не хотим идти путём бизнеса. Реклама, кампании и инвесторы рано или поздно убивают дух идеи.",
  "pack.misia.v3": "*Но ничего не бывает бесплатно.* Серверы, разработка приложения, люди и сервисы каждый месяц стоят денег. Чем больше из этого покроют *добровольные пожертвования* стаи, тем открытее сможет остаться DOGYPT.",
  "pack.misia.v4": "Хватит немногого. Когда нас станет больше, мы оплатим работу и развитие, а остальное пойдёт собакам: тем, кто в беде, исследованиям здоровья и новому снаряжению.",
  "pack.misia.v5": "Казна открыта. Ты видишь, что пришло и куда ушло, а куда пойдёт дальше, мы решим вместе.",
  "pack.misia.v6": "*Безопасное место для нас и наших собак.*",
  "pack.misia.fixed": "Текущие ежемесячные расходы",
  "pack.misia.fixed.p": "Их покроют {n} участников по 3,99 € в месяц. Сейчас их {g}.",
