  "pack.flow.z_kastr.t": "Может ли он размножаться?",
  "pack.flow.z_kastr.o.yes": "Нет, он стерилизован (вазэктомия)",
  "pack.flow.z_kastr.o.yes.warn": "<b>По последним данным, лучше выбрать вазэктомию.</b> Она механически предотвращает оплодотворение, а гормоны сохраняются; у самки можно сохранить яичники. Классическую кастрацию делай только после взросления: это зависит от развития и породы, кобеля и суку не раньше окончания полового созревания, крупные породы как можно позже. У французских бульдогов кастрация до 12 месяцев повышала риск проблем с межпозвоночными дисками примерно в 2 раза у кобелей и примерно в 10 раз у сук.",
  "pack.flow.z_kastr.o.yes.warnT": "Почему вазэктомия",
