  "pack.flow.z_kastr.o.no.sub.kennel.warn": "Разводить собак допустимо, только если животное живёт в достойных условиях, под профессиональным надзором, с известной родословной и историей.",
  "pack.flow.z_kastr.o.no.sub.kennel.warnT": "Что важно знать о разведении",
  "pack.flow.z_kastr.o.no.sub.plan_neuter": "Мы планируем его кастрировать",
  "pack.flow.z_kastr.o.no.sub.plan_neuter.warn": "<b>По последним данным, лучше выбрать вазэктомию.</b> Она механически предотвращает оплодотворение, а гормоны сохраняются; у самки можно сохранить яичники. Классическую кастрацию делай только после взросления: это зависит от развития и породы, кобеля и суку не раньше окончания полового созревания, крупные породы как можно позже. У французских бульдогов кастрация до 12 месяцев повышала риск проблем с межпозвоночными дисками примерно в 2 раза у кобелей и примерно в 10 раз у сук.",
  "pack.flow.z_kastr.o.no.sub.plan_neuter.warnT": "Почему вазэктомия",
  "pack.flow.z_kastr.o.no.sub.puppies": "Хотим щенков, это же мило",
  "pack.flow.z_kastr.o.no.sub.puppies.warn": "Разводить собак без документов незаконно. В этом мире слишком много ненужных собак в приютах без шанса выбраться, в том числе из-за нелегального разведения и «новых» щенков. Кто разводит собак таким способом, совершает грех против собачьего рода. Собаке не нужно потомство; за этим стоят лишь человеческие сантименты и надежда на прибыль. Правда в том, что этот путь не приносит ничего, кроме страданий.",
