  "pack.flow.z_lieky.f0.ph": "Например: омега-3, 1 капсула утром",
  "pack.flow.z_ocko.t": "Когда была последняя прививка?",
  "pack.flow.z_ocko.note": "Титры, пропущенные вакцины, реакция после прививки.",
  "pack.flow.z_ocko.tip0": "<b>Комплексная вакцина</b> представляет собой одну инъекцию против нескольких болезней: чумы плотоядных, парвовироза, гепатита, часто и лептоспироза. В ветпаспорте она обозначена как DHPPi/L.",
  "pack.flow.z_ocko.tip1": "<b>Прививка от бешенства обязательна по человеческим законам</b>, и тест на антитела юридически её не заменяет. Но в собачьем мире избыточная вакцинация может навредить: антитела находят у собаки и спустя много лет, иногда всю жизнь, поэтому повторные прививки часто бессмысленны или даже вредны. Если не хочешь вводить собаке лишние вакцины, есть анализ крови на антитела. Если они есть, подумай, стоит ли прививать.",
  "pack.flow.z_ocko.tipT": "Что важно знать о прививках",
  "pack.flow.z_ocko.f0": "Бешенство",
  "pack.flow.z_ocko.f1": "Комплексная вакцина",
  "pack.flow.z_parazity.t": "Как ты решаешь вопрос с кишечными паразитами?",
  "pack.flow.z_parazity.tip0": "<b>Совет: сначала анализ кала.</b> Копрологическое исследование покажет, есть ли что лечить. Задумайся, правильно ли кормить собаку химией просто на всякий случай. Регулярные таблетки не так безобидны, как кажется. Это бизнес, за который платит здоровье собак. Используй их, только когда это необходимо и имеет смысл, то есть при наличии паразита.",
  "pack.flow.z_parazity.tipT": "Что важно знать о паразитах",
  "pack.flow.z_parazity.o.stool": "По анализу кала",
